// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the bricks and the paddle. Brick resolution is swept and resolves
// ONE collision per pass, so the ball never tunnels (level 6, dt = 0.05: step
// 35.5px > brick 34px) and never has an axis flipped twice on a grid seam
// (BRICK_GAP 8px < ball diameter 14px).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const x0 = ball.x;
  const y0 = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Bricks: resolve the earliest hit along the ball's path this step. Only the
  // nearest collision is processed — processing every overlapped brick in a
  // seam would flip the same axis twice and let the ball through (ghost
  // collision). The ball is snapped to the face it entered, so no overlap is
  // left behind (no sticky contact on the next frame).
  let hit = null;
  let hitBrick = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const candidate = sweptHit(ball, brick, x0, y0, ball.x, ball.y);
    if (candidate && (!hit || candidate.t < hit.t)) {
      hit = candidate;
      hitBrick = brick;
    }
  }
  if (hitBrick) {
    destroyBrick(state, hitBrick);
    // Snap the ball to the entry point of the face it hit.
    ball.x = x0 + ball.vx * dt * hit.t;
    ball.y = y0 + ball.vy * dt * hit.t;
    if (hit.face === 'x' || hit.face === 'corner') {
      pushOutX(ball, hitBrick);
    }
    if (hit.face === 'y' || hit.face === 'corner') {
      pushOutY(ball, hitBrick);
    }
  } else {
    // Static fallback: the ball already overlaps a brick (pre-existing
    // penetration). Resolve by least penetration; equal penetrations mean a
    // corner and flip both axes.
    for (const brick of state.bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;
      const overlapX = Math.min(
        ball.x + ball.r - brick.x,
        brick.x + brick.w - (ball.x - ball.r)
      );
      const overlapY = Math.min(
        ball.y + ball.r - brick.y,
        brick.y + brick.h - (ball.y - ball.r)
      );
      destroyBrick(state, brick);
      if (Math.abs(overlapX - overlapY) < 1e-9) {
        pushOutX(ball, brick);
        pushOutY(ball, brick);
      } else if (overlapX < overlapY) {
        pushOutX(ball, brick);
      } else {
        pushOutY(ball, brick);
      }
      break; // one resolution per pass
    }
  }

  // Paddle: bounce when the ball's bottom crosses the paddle's top plane
  // during this step (a band test `ball.y + r in [paddle.y, paddle.y + h]`
  // lets a step longer than PADDLE_H = 12px — 13px at level 1, dt = 0.05 —
  // skip the paddle entirely).
  if (
    ball.vy > 0 &&
    ball.x + ball.r > paddle.x &&
    ball.x - ball.r < paddle.x + paddle.w
  ) {
    const prevBottom = ball.y - ball.vy * dt + ball.r;
    if (prevBottom <= paddle.y && ball.y + ball.r >= paddle.y) {
      ball.y = paddle.y - ball.r;
      // Rebound angle from the impact point. |hit| is floored so the exact
      // center never yields a vertical trajectory (dead angle), then the
      // velocity is renormalized so the post-bounce speed is exactly the
      // level speed.
      const hit = clamp(
        (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2),
        -1,
        1
      );
      const hitF = (hit >= 0 ? 1 : -1) * Math.max(Math.abs(hit), MIN_PADDLE_HIT);
      const speed = ballSpeed(state.level);
      const vx = speed * PADDLE_SPIN * hitF;
      const vy = -speed;
      const norm = Math.hypot(vx, vy);
      ball.vx = (vx / norm) * speed;
      ball.vy = (vy / norm) * speed;
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

