// --- Brick collision resolution (pure logic, used by step()) ---------------

// Time window during which the point moving from p0 to p1 stays inside the
// slab [min, max] on one axis, as a fraction of the step (Liang-Barsky), or
// null if it never does. Returns [entry, exit].
function slab(p0, p1, min, max) {
  const v = p1 - p0;
  if (Math.abs(v) < 1e-12) {
    if (p0 < min || p0 > max) return null;
    return [-Infinity, Infinity];
  }
  return [
    Math.min((min - p0) / v, (max - p0) / v),
    Math.max((min - p0) / v, (max - p0) / v),
  ];
}

// Swept test: does the ball's path from (x0, y0) to (x1, y1) enter the brick
// (inflated by the ball radius) during this step? Returns the earliest entry
// time and the face entered ('x' side, 'y' side, or 'corner' when both faces
// are crossed at the same instant), or null. Testing the path instead of the
// end position is what stops a step longer than the brick from tunneling
// through it (BRICK_H + 2*BALL_R = 34px, max step 35.5px at level 6, dt 0.05).
function sweptHit(ball, brick, x0, y0, x1, y1) {
  const tx = slab(x0, x1, brick.x - ball.r, brick.x + brick.w + ball.r);
  const ty = slab(y0, y1, brick.y - ball.r, brick.y + brick.h + ball.r);
  if (!tx || !ty) return null;
  const tEntry = Math.max(tx[0], ty[0]);
  const tExit = Math.min(tx[1], ty[1]);
  if (tEntry > tExit || tEntry <= 0 || tEntry > 1) return null;
  if (Math.abs(tx[0] - ty[0]) < 1e-9) return { t: tEntry, face: 'corner' };
  return { t: tEntry, face: tx[0] > ty[0] ? 'x' : 'y' };
}

// Kills the brick and awards the score, combo included. Called once per
// resolved collision, so a brick is always counted exactly once.
function destroyBrick(state, brick) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}

// Pushes the ball out of the brick along x, back to the face it entered from
// (the side opposite its motion), and flips vx.
function pushOutX(ball, brick) {
  const fromLeft = ball.vx > 0 || (ball.vx === 0 && ball.x < brick.x + brick.w / 2);
  ball.x = fromLeft ? brick.x - ball.r : brick.x + brick.w + ball.r;
  ball.vx = -ball.vx;
}

// Same as pushOutX, along y (and flipping vy).
function pushOutY(ball, brick) {
  const fromTop = ball.vy > 0 || (ball.vy === 0 && ball.y < brick.y + brick.h / 2);
  ball.y = fromTop ? brick.y - ball.r : brick.y + brick.h + ball.r;
  ball.vy = -ball.vy;
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the bricks and the paddle. Brick resolution is swept and resolves
// ONE collision per pass, so the ball never tunnels (level 6, dt = 0.05: step
// 35.5px > brick 34px) and never has an axis flipped twice on a grid seam
// (BRICK_GAP 8px < ball diameter 14px).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const x0 = ball.x;
  const y0 = ball.y;

  ball.x += ball.vx * dt;

