    if (prevBottom <= paddle.y && ball.y + ball.r >= paddle.y) {
      ball.y = paddle.y - ball.r;
      // Rebound angle from the impact point. |hit| is floored so the exact
      // center never yields a vertical trajectory (dead angle), then the
      // velocity is renormalized so the post-bounce speed is exactly the
      // level speed.
      const hit = clamp(
        (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2),
        -1,
        1
      );
      const hitF = (hit >= 0 ? 1 : -1) * Math.max(Math.abs(hit), MIN_PADDLE_HIT);
      const speed = ballSpeed(state.level);
      const vx = speed * PADDLE_SPIN * hitF;
      const vy = -speed;
      const norm = Math.hypot(vx, vy);
      ball.vx = (vx / norm) * speed;
      ball.vy = (vy / norm) * speed;
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

